class Solution {
    public int snakesAndLadders(int[][] board){
        int n=board.length,target=n*n;
        Queue<int[]> queue=new ArrayDeque<>();
        boolean[] seen=new boolean[target+1];
        queue.offer(new int[]{
            1,0
        });
        seen[1]=true;
        while(!queue.isEmpty()){
            int[] state=queue.poll();
            if(state[0]==target)return state[1];
            for(int next=state[0]+1;next<=Math.min(target,state[0]+6);next++){
                int quotient=(next-1)/n,row=n-1-quotient,column=(next-1)%n;
                if(quotient%2==1)column=n-1-column;
                int destination=board[row][column]==-1?next:board[row][column];
                if(!seen[destination]){
                    seen[destination]=true;
                    queue.offer(new int[]{
                        destination,state[1]+1
                    });
                }
            }
        }
        return -1;
    }
}

