class Solution {
    public: int snakesAndLadders(vector<vector<int>>& board){
        int n=board.size(),target=n*n;
        queue<pair<int,int>> pending;
        vector<bool> seen(target+1);
        pending.push({
            1,0
        });
        seen[1]=true;
        while(!pending.empty()){
            auto [label,distance]=pending.front();
            pending.pop();
            if(label==target)return distance;
            for(int next=label+1;next<=min(target,label+6);++next){
                int quotient=(next-1)/n,row=n-1-quotient,column=(next-1)%n;
                if(quotient%2)column=n-1-column;
                int destination=board[row][column]==-1?next:board[row][column];
                if(!seen[destination]){
                    seen[destination]=true;
                    pending.push({
                        destination,distance+1
                    });
                }
            }
        }
        return -1;
    }
};
